//! Source-checked online service metadata and complete Wiki directory.
use crate::*;
use crate::validate::{date,ensure,public_url,stable_id,text_fields};
use chrono::Utc;
use std::collections::BTreeSet;
pub fn validate_online(data:&Value,tools:&[Value],jobs:&[Value])->Result<()> {
 fn reviewed(v:&Value,label:&str)->Result<chrono::NaiveDate>{let d=date(v).ok_or_else(||format!("{label}: invalid or future review date"))?;ensure(d<=Utc::now().date_naive(),format!("{label}: invalid or future review date"))?;Ok(d)}
 ensure(data["schemaVersion"]==1,"Online tools require schemaVersion 1")?;let review_date=reviewed(&data["reviewedAt"],"Online directory")?;for key in ["groups","tools","workflows","featured"]{ensure(!a(&data[key]).is_empty(),format!("Online {key} must be a nonempty list"))?;}let catalog=index(tools,"id");let job_ids=ids(jobs,"id");let groups=ids(a(&data["groups"]),"id");let entries=a(&data["tools"]);let online_ids=ids(entries,"toolId");ensure(groups.len()==a(&data["groups"]).len()&&online_ids.len()==entries.len(),"Online tools and groups require unique identities")?;for g in a(&data["groups"]){ensure(stable_id(s(g,"id")),"Online group: a stable slug ID is required")?;text_fields(g,&["label","summary"],s(g,"id"))?;}let featured: BTreeSet<_>=a(&data["featured"]).iter().map(t).collect();ensure(featured.len()==a(&data["featured"]).len()&&featured.iter().all(|id|online_ids.contains(*id)),"Featured online tools must be unique and exist in the online catalog")?;ensure(online_ids==tools.iter().filter(|t|s(t,"category")=="online").map(|t|s(t,"id").to_string()).collect(),"Online metadata must cover every online catalog tool exactly once")?;for e in entries{let id=s(e,"toolId");ensure(stable_id(id),"Online tool: a stable slug ID is required")?;ensure(catalog.get(id).is_some()&&groups.contains(s(e,"group")),format!("Unknown online relationship: {id}"))?;text_fields(e,&["account","sharing","firstAction","expectedResult","reviewedAt"],id)?;ensure(!a(&e["sources"]).is_empty(),format!("{id}: missing online sources"))?;ensure(s(&catalog[id],"mode")=="web",format!("{id}: online tools must be labeled web services"))?;ensure(reviewed(&e["reviewedAt"],id)?<=review_date,format!("{id}: review date is newer than the directory review"))?;for source in a(&e["sources"]){ensure(public_url(&source["url"],true),format!("{id}: each claim needs a public HTTPS source without tracking"))?;text_fields(source,&["title","evidence"],id)?;}}
 ensure(ids(entries,"group")==groups,"Every online group must contain tools")?;let mut workflows=BTreeSet::new();for w in a(&data["workflows"]){let id=s(w,"id");ensure(stable_id(id),"Online workflow: a stable slug ID is required")?;text_fields(w,&["title","summary"],id)?;ensure(workflows.insert(id)&&job_ids.contains(s(w,"jobId")),"Online workflows require unique IDs and an existing full guide")?;let tids=a(&w["toolIds"]);ensure(a(&w["steps"]).len()==3&&!tids.is_empty()&&tids.iter().map(t).collect::<BTreeSet<_>>().len()==tids.len()&&tids.iter().all(|v|online_ids.contains(t(v))),format!("{id}: use three first actions and real catalog tools"))?;ensure(a(&w["steps"]).iter().all(|v|!t(v).trim().is_empty()),format!("{id}.step: nonempty text is required"))?;}Ok(())
}
fn tool_link(id:&str,tools:&Value,access:&Value)->String{format!("[{}]({})",s(&tools[id],"name"),s(&access[id]["primary"],"url"))}
pub fn start_markdown(data:&Value,tools:&Value,access:&Value)->String{
 let mut l=lines!["## 🌐 Online tools: open a service and get a result","",format!("**[Browse all {} online tools]({HUB}#online)** · **[Online tools Wiki]({WIKI}/Online-Tools)**",a(&data["tools"]).len()),"","| Your job | Open the right tools | First action |","| --- | --- | --- |"];
 for w in a(&data["workflows"]){l.push(format!("| **[{}]({HUB}#online?task={})** | {} | {} |",s(w,"title"),s(w,"id"),a(&w["toolIds"]).iter().map(|id|tool_link(t(id),tools,access)).collect::<Vec<_>>().join(" · "),cell(&w["steps"][0])));}
 l.extend(lines!["","Service links open their official websites. Account, access and submission visibility are shown beside the tools in the directory.",""]);l.join("\n")
}
pub fn wiki_outputs(data:&Value,catalog:&[Value],access:&Value)->Outputs{
 let tools=index(catalog,"id");let entries=a(&data["tools"]);let mut l=lines!["# 🌐 Online tools","",format!("**{} services across {} practical groups. Source review: {}.**",entries.len(),a(&data["groups"]).len(),s(data,"reviewedAt")),"",format!("**[Open the searchable working directory]({HUB}#online)** · [Complete tool catalog](Tool-Directory) · [Home](Home)"),"","Choose the job first. Each service has a direct launch, a concrete first action, an expected result and its account and sharing behavior. The date records an editorial source review, not a claim that every service is a new release or was tested with a live incident.","",start_markdown(data,&tools,access),"## Browse by task",""];
 l.extend(a(&data["groups"]).iter().map(|g|format!("- **[{}](Online-{})**: {}",s(g,"label"),s(g,"id"),s(g,"summary"))));l.extend(lines!["","## Work through a result",""]);for w in a(&data["workflows"]){l.extend(lines![format!("<a id=\"{}\"></a>",s(w,"id")),"",format!("### {}",s(w,"title")),"",s(w,"summary"),"",a(&w["toolIds"]).iter().map(|id|tool_link(t(id),&tools,access)).collect::<Vec<_>>().join(" · "),""]);l.extend(a(&w["steps"]).iter().enumerate().map(|(i,v)|format!("{}. {}",i+1,t(v))));l.extend(lines!["",format!("**Continue:** [Complete job guide]({WIKI}/Job-{}) · [Interactive toolkit]({HUB}#job/{})",s(w,"jobId"),s(w,"jobId")),""]);}
 let mut out=Outputs::new();out.insert("wiki/Online-Tools.md".into(),l.join("\n"));for g in a(&data["groups"]){let group_entries:Vec<_>=entries.iter().filter(|e|e["group"]==g["id"]).collect();let mut c=lines![format!("# {}",s(g,"label")),"",s(g,"summary"),"",format!("**[Filter these tools in the app]({HUB}#online?group={})** · [All online tools](Online-Tools)",s(g,"id")),"",group_entries.iter().map(|e|tool_link(s(e,"toolId"),&tools,access)).collect::<Vec<_>>().join(" | "),""];
 for e in group_entries{let id=s(e,"toolId");let tool=&tools[id];c.extend(lines![format!("<a id=\"{id}\"></a>"),"",format!("## {}",tool_link(id,&tools,access)),"",s(tool,"summary"),"",format!("**[Open service]({})** · [Official page]({}) · [Documentation]({})",s(&access[id]["primary"],"url"),s(&access[id],"officialUrl"),s(tool,"docsUrl")),"",format!("**[Open this tool's working notes]({HUB}#online?tool={id})**"),"",format!("**Use for:** {}",s(tool,"bestFor")),"",format!("**Start here:** {}",s(e,"firstAction")),"",format!("**Read the result:** {}",s(e,"expectedResult")),"",format!("**Access:** {} {}",s(tool,"pricing"),s(e,"account")),"",format!("**Submission behavior:** {}",s(e,"sharing")),"","**Official evidence:**",""]);c.extend(a(&e["sources"]).iter().map(|v|format!("- [{}]({}): {}",s(v,"title"),s(v,"url"),s(v,"evidence"))));c.extend(lines!["",format!("Reviewed {}. [Back to all online tools](Online-Tools).",s(e,"reviewedAt")),""]);}out.insert(format!("wiki/Online-{}.md",s(g,"id")),c.join("\n"));}out
}
